/**
 * Menu's command list on right-click or long-press, at the press point (`design/components/context-menu.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/context-menu.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/menu'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  afresh,
  agentMember,
  chooseMenuEntry,
  claimSlot,
  classes,
  createCell,
  createDerived,
  elementRef,
  followHighlight,
  menuChoices,
  mergeParts,
  ownerContext,
  provide,
  scope,
  useDirection,
  useMachine,
  useMediaQuery,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/context-menu.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import ContextMenuSubmenu from './ContextMenuSubmenu'
import Kbd from '../structure/Kbd'
import type { MenuEntry } from './Menu'

export interface ContextMenuProps {
  /**
   * The surface: one element, which may be non-interactive, because the trigger is the area, not
   * a control. The member merges into the child instead of wrapping it in a box. A wrapper
   * element around a `Table.Row` would break the table, and the panel anchors to the press
   * point, so the trigger span's rect is never needed.
   */
  children: JSX.Element
  /**
   * Entries in Menu's grammar (`menu.md`), including submenus; this member does not redefine it.
   */
  entries: MenuEntry[]
  /**
   * Notifies apps that pause row hover states or refresh entries on open.
   */
  onOpenChange?: (open: boolean) => void
  /**
   * Menu's `presentation`, passed through (`menu.md`; the sheet presentation): `'auto'` uses a
   * sheet below `30rem`, and `'popover'` keeps the press-point popper at every width. Like
   * Menu's, the union is closed and has no always-`'sheet'` value.
   */
  presentation?: 'auto' | 'popover'
}

/** What ContextMenu hands its compound parts. */
export interface ContextMenuOwner {
  readonly api: zag.Api
  readonly service: zag.Service
}

/** Menu's command list on right-click or long-press, at the press point. */
export default function ContextMenu(given: ContextMenuProps): JSX.Element {
  const props = mergeProps(
    { presentation: 'auto' } as Defaults<ContextMenuProps, 'presentation'>,
    claimSlot(given),
  )
  return scope(() => {
    provide(ownerContext<ContextMenuOwner>('ContextMenu'), {
      get api() {
        return api.value
      },
      get service() {
        return service
      },
    })
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const sheetPanel = elementRef<HTMLElement>()
    const surface = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const restoreTo = createCell(null as HTMLElement | null)
    const sheeting = createDerived(() => props.presentation === 'auto' && phone())
    const flat = createDerived(() =>
      props.entries.flatMap((entry) =>
        entry.kind === 'submenu'
          ? [{ kind: 'label' as const, label: entry.label }, ...(entry.disabled ? [] : entry.items)]
          : [entry],
      ),
    )
    const remember = createDerived(() => (pressed: boolean) => {
      const active = document.activeElement
      const focused = active instanceof HTMLElement && active !== document.body ? active : null
      restoreTo.value = pressed ? focused : (focused ?? restoreTo.value)
    })
    const documentDirection = useDirection(() => surface.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          positioning: { placement: 'right-start', gutter: 0 },
          onOpenChange: (details) => {
            props.onOpenChange?.(details.open)
          },
          onSelect: (details) => {
            flat.value.forEach(
              (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
            )
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const present = usePresence(
      () => api.value.open && !sheeting.value,
      () => panel.value,
    )
    const sheetPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => sheetPanel.value,
      'sheet.panel',
      { sheetSide: 'bottom' },
    )
    const scrimPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => scrim.value,
      'dialog.scrim',
    )
    const effect1 = () => {
      followHighlight(panel.value, api.value.highlightedValue)
    }
    watchEffect(
      createMemo(() => api.value.highlightedValue),
      effect1,
      true,
    )
    const effect2 = () => {
      void (
        api.value.open ||
        requestAnimationFrame(() => (restoreTo.value?.focus(), (restoreTo.value = null)))
      )
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect2,
      false,
    )
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = agentMember({
        member: 'ContextMenu',
        element: () => surface.value,
        state: () => ({ open: api.value.open, entries: menuChoices(props.entries) }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) =>
              chooseMenuEntry(props.entries, value) && api.value.open && api.value.setOpen(false),
          },
        },
      })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <>
        {/* surface */}
        <span
          {...mergeParts(api.value.getContextTriggerProps(), {
            class: styles.surface,
            style: { 'user-select': 'auto', '-webkit-user-select': 'auto' },
            'data-member': 'context-menu',
            'oncapture:contextmenu': () => remember.value(false),
            'oncapture:pointerdown': () => remember.value(true),
          })}
          ref={surface.attach}
        >
          {props.children}
        </span>
        <Portal>
          {afresh(() => (
            <>
              {present() ? (
                <div {...mergeParts(api.value.getPositionerProps())}>
                  {/* panel */}
                  <div
                    {...mergeParts(api.value.getContentProps(), {
                      class: styles.content,
                      style: {
                        '--radix-context-menu-content-available-height': 'var(--available-height)',
                        '--radix-context-menu-content-transform-origin': 'var(--transform-origin)',
                      },
                      hidden: undefined,
                      'data-member': 'context-menu',
                      onfocus: () => followHighlight(panel.value, api.value.highlightedValue),
                    })}
                    ref={panel.attach}
                  >
                    <Each of={props.entries} by={(_entry, index) => index} renew>
                      {(entry) => (
                        <>
                          {entry.kind === 'separator' ? (
                            <div
                              {...mergeParts(api.value.getSeparatorProps(), {
                                class: styles.separator,
                              })}
                            />
                          ) : entry.kind === 'label' ? (
                            <div class={styles.groupLabel}>{entry.label}</div>
                          ) : entry.kind === 'checkbox' ? (
                            <div
                              {...mergeParts(
                                api.value.getOptionItemProps({
                                  type: 'checkbox',
                                  value: entry.label,
                                  checked: entry.checked,
                                  disabled: entry.disabled,
                                  closeOnSelect: false,
                                  onCheckedChange: entry.onCheckedChange,
                                }),
                                {
                                  class: classes(styles.item, styles.checkbox),
                                  tabindex: '-1',
                                  onfocus: () => api.value.setHighlightedValue(entry.label),
                                },
                              )}
                            >
                              <span class={styles.check}>
                                {entry.checked ? <Icon name="confirm" size="sm" /> : null}
                              </span>
                              <span class={styles.label}>{entry.label}</span>
                            </div>
                          ) : entry.kind === 'submenu' ? (
                            <ContextMenuSubmenu entry={entry} />
                          ) : (
                            <div
                              {...mergeParts(
                                api.value.getItemProps({
                                  value: entry.label,
                                  disabled: entry.disabled,
                                }),
                                {
                                  class: styles.item,
                                  'data-tone': entry.tone ?? 'neutral',
                                  tabindex: '-1',
                                  onfocus: () => api.value.setHighlightedValue(entry.label),
                                },
                              )}
                            >
                              {entry.icon !== undefined ? (
                                <span class={styles.glyph}>
                                  <Icon name={entry.icon} size="sm" />
                                </span>
                              ) : null}
                              <span class={styles.label}>{entry.label}</span>
                              {entry.kbd !== undefined ? (
                                <span class={styles.hint}>
                                  <Kbd>{entry.kbd}</Kbd>
                                </span>
                              ) : null}
                            </div>
                          )}
                        </>
                      )}
                    </Each>
                  </div>
                </div>
              ) : null}
              {scrimPresent() ? (
                <div
                  class={sheet.scrim}
                  data-state={api.value.open ? 'open' : 'closed'}
                  ref={scrim.attach}
                />
              ) : null}
              {sheetPresent() ? (
                <div class={sheet.positioner}>
                  <div
                    class={sheet.panel}
                    data-presentation="sheet"
                    data-state={api.value.open ? 'open' : 'closed'}
                    tabindex="-1"
                    ref={sheetPanel.attach}
                  >
                    {/* panel */}
                    <div
                      {...mergeParts(api.value.getContentProps(), {
                        class: styles.sheetList,
                        hidden: undefined,
                        'data-member': 'context-menu',
                        onfocus: () => followHighlight(panel.value, api.value.highlightedValue),
                      })}
                      ref={panel.attach}
                    >
                      <Each of={flat.value} by={(_entry, index) => index} renew>
                        {(entry) => (
                          <>
                            {entry.kind === 'separator' ? (
                              <div
                                {...mergeParts(api.value.getSeparatorProps(), {
                                  class: styles.separator,
                                })}
                              />
                            ) : entry.kind === 'label' ? (
                              <div class={styles.groupLabel}>{entry.label}</div>
                            ) : entry.kind === 'checkbox' ? (
                              <div
                                {...mergeParts(
                                  api.value.getOptionItemProps({
                                    type: 'checkbox',
                                    value: entry.label,
                                    checked: entry.checked,
                                    disabled: entry.disabled,
                                    closeOnSelect: false,
                                    onCheckedChange: entry.onCheckedChange,
                                  }),
                                  {
                                    class: classes(styles.item, styles.checkbox),
                                    tabindex: '-1',
                                    onfocus: () => api.value.setHighlightedValue(entry.label),
                                  },
                                )}
                              >
                                <span class={styles.check}>
                                  {entry.checked ? <Icon name="confirm" size="sm" /> : null}
                                </span>
                                <span class={styles.label}>{entry.label}</span>
                              </div>
                            ) : (
                              <div
                                {...mergeParts(
                                  api.value.getItemProps({
                                    value: entry.label,
                                    disabled: entry.disabled,
                                  }),
                                  {
                                    class: styles.item,
                                    'data-tone': entry.tone ?? 'neutral',
                                    tabindex: '-1',
                                    onfocus: () => api.value.setHighlightedValue(entry.label),
                                  },
                                )}
                              >
                                {entry.icon !== undefined ? (
                                  <span class={styles.glyph}>
                                    <Icon name={entry.icon} size="sm" />
                                  </span>
                                ) : null}
                                <span class={styles.label}>{entry.label}</span>
                                {entry.kbd !== undefined ? (
                                  <span class={styles.hint}>
                                    <Kbd>{entry.kbd}</Kbd>
                                  </span>
                                ) : null}
                              </div>
                            )}
                          </>
                        )}
                      </Each>
                    </div>
                  </div>
                </div>
              ) : null}
            </>
          ))}
        </Portal>
      </>
    )
  })
}
